static const uint8_t BLANK_ASCII[48] = {0};
static const uint8_t BLANK_CJK[128] = {0};
static const uint8_t BLANK_DATE_DIGIT[432] = {0};

const uint8_t *manual_font_ascii_rows(uint8_t codepoint)
{
    if (codepoint < 0x20 || codepoint > 0x7e) return BLANK_ASCII;
    return ASCII_GLYPHS[codepoint - 0x20];
}

const uint8_t *manual_font_cjk_rows(uint32_t codepoint)
{
    for (unsigned i = 0; i < sizeof(CJK_GLYPHS) / sizeof(CJK_GLYPHS[0]); ++i) {
        if (CJK_GLYPHS[i].codepoint == codepoint) return CJK_GLYPHS[i].rows;
    }
    const uint8_t *rows = NULL;
    if (font_store_lookup(codepoint, &rows)) {
        return rows;
    }
    return BLANK_CJK;
}

const uint8_t *manual_font_date_digit_rows(uint8_t digit)
{
    return digit < 10 ? DATE_DIGITS[digit] : BLANK_DATE_DIGIT;
}
